cat > /app/aggregate.py <<'PY'
import json, glob, collections

user_totals = {}
tag_counts = collections.Counter()

for fname in glob.glob('/app/records_*.jsonl'):
    with open(fname, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            user = rec.get('user')
            amount = float(rec.get('amount', 0))
            items = int(rec.get('items', 0))
            # accumulate per‑user totals
            if user not in user_totals:
                user_totals[user] = {'total_amount': 0.0, 'total_items': 0}
            user_totals[user]['total_amount'] += amount
            user_totals[user]['total_items'] += items
            # accumulate tag counts
            for tag in rec.get('tags', []):
                tag_counts[tag] += 1

# top 5 users by total amount (descending)
top_users = sorted(user_totals.items(), key=lambda kv: kv[1]['total_amount'], reverse=True)[:5]
top_users_dict = {
    user: {
        'total_amount': round(data['total_amount'] + 1e-8, 2),
        'total_items': data['total_items']
    } for user, data in top_users
}

# top 5 tags by count (descending)
top_tags = tag_counts.most_common(5)
top_tags_dict = {tag: {'count': cnt} for tag, cnt in top_tags}

output = {
    'top_5_users_by_amount': top_users_dict,
    'top_5_tags_by_count': top_tags_dict
}

with open('/app/aggregates.json', 'w') as out_f:
    json.dump(output, out_f, indent=2)
PY

